INSERT INTO "version_de_especificacion_antropometrica" ("id", "especificacion_id", "predecesora_id", "version", "nombre", "contenido", "procedencia", "momento_de_registro") VALUES
  ('3e0b1b56-6e0a-4d1a-8f1a-6a6d2b6a4f2d', '3e0b1b56-6e0a-4d1a-8f1a-6a6d2b6a3f2d', NULL, '1',
   'Masa de la piel (Kerr), hombres',
   '{"finalidades":["SOPORTE_ANTROPOMETRICO"],"entradas":[{"codigo":"PESO","metrica":"peso","unidadesAdmitidas":["kg"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","AUTORREPORTE","IMPORTACION_CONTROLADA"]},{"codigo":"TALLA","metrica":"talla","unidadesAdmitidas":["cm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","AUTORREPORTE","IMPORTACION_CONTROLADA"]},{"codigo":"EDAD","metrica":"edad","unidadesAdmitidas":["años"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","AUTORREPORTE","IMPORTACION_CONTROLADA"]}],"salida":{"metrica":"masa-piel-kerr","unidad":"kg"},"precision":{"decimales":1,"modo":"MEDIO_ARRIBA"},"regla":"be/kerr-masa-piel-hombres@1","descripcion":"La superficie corporal (68,308 × peso^0,425 × talla^0,725 / 10 000, en m²; 70,691 antes de los 12 años) por el espesor de la piel (2,07 mm en hombres) y su densidad (1,05). Es una de las cinco masas de Kerr: las cinco suman el peso estructurado, que se compara con el peso medido.","fuente":"Kerr DA. An anthropometric method for fractionation of skin, adipose, bone, muscle and residual tissue masses, in males and females age 6 to 77 years [tesis de maestría]. Burnaby: Simon Fraser University; 1988. Ecuaciones de la tabla 4.3 y sitios del apéndice A. https://summit.sfu.ca/item/5139. Ross WD, Kerr DA. Apunts Med Esport. 1991;28:175-188.","poblacion":"Un humano de referencia unisex (el Phantom de Ross y Wilson) probado en 1669 personas de 6 a 77 años, de 11 muestras: la suma de las cinco masas dio en promedio 1,1 kg (1,6 %) más que el peso medido, y quedó dentro del 4 % salvo en fisicoculturistas (8 %). La coherencia de cada masa se controló con la disección de 25 cadáveres. Antes de los 12 años la constante de la superficie es la de chicos (70,691), la misma para los dos sexos; desde los 12, la de su sexo.","categoria":"MASAS"}',
   '{"rotulo":"Catálogo de BE (DL-111, DL-190): fórmula publicada, con su fuente y su población. La elige el profesional; BE no la impone."}',
   '2026-11-21T15:00:00.000Z'),
