  ('3e0b1b56-6e0a-4d1a-8f1a-6a6d2b6a4f30', '3e0b1b56-6e0a-4d1a-8f1a-6a6d2b6a3f30', NULL, '1',
   'Masa muscular (Kerr)',
   '{"finalidades":["SOPORTE_ANTROPOMETRICO"],"entradas":[{"codigo":"TALLA","metrica":"talla","unidadesAdmitidas":["cm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","AUTORREPORTE","IMPORTACION_CONTROLADA"]},{"codigo":"PERIMETRO_BRAZO_RELAJADO","metrica":"perimetro-brazo-relajado","unidadesAdmitidas":["cm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","IMPORTACION_CONTROLADA"]},{"codigo":"PLIEGUE_TRICEPS","metrica":"pliegue-triceps","unidadesAdmitidas":["mm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","IMPORTACION_CONTROLADA"]},{"codigo":"PERIMETRO_ANTEBRAZO","metrica":"perimetro-antebrazo","unidadesAdmitidas":["cm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","IMPORTACION_CONTROLADA"]},{"codigo":"PERIMETRO_MUSLO_GLUTEO","metrica":"perimetro-muslo-gluteo","unidadesAdmitidas":["cm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","IMPORTACION_CONTROLADA"]},{"codigo":"PLIEGUE_MUSLO_FRONTAL","metrica":"pliegue-muslo-frontal","unidadesAdmitidas":["mm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","IMPORTACION_CONTROLADA"]},{"codigo":"PERIMETRO_PANTORRILLA","metrica":"perimetro-pantorrilla","unidadesAdmitidas":["cm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","IMPORTACION_CONTROLADA"]},{"codigo":"PLIEGUE_PANTORRILLA","metrica":"pliegue-pantorrilla","unidadesAdmitidas":["mm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","IMPORTACION_CONTROLADA"]},{"codigo":"PERIMETRO_PECHO","metrica":"perimetro-pecho","unidadesAdmitidas":["cm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","IMPORTACION_CONTROLADA"]},{"codigo":"PLIEGUE_SUBESCAPULAR","metrica":"pliegue-subescapular","unidadesAdmitidas":["mm"],"procedenciasAdmitidas":["CAPTURA_DIRECTA","IMPORTACION_CONTROLADA"]}],"salida":{"metrica":"masa-muscular-kerr","unidad":"kg"},"precision":{"decimales":1,"modo":"MEDIO_ARRIBA"},"regla":"be/kerr-masa-muscular@1","descripcion":"Escala al Phantom, con la talla, la suma de cinco perímetros: brazo relajado, muslo a 1 cm del pliegue glúteo, pantorrilla y pecho mesoesternal, cada uno corregido por su pliegue (perímetro − π × pliegue / 10), y el antebrazo sin corregir. El muslo no es el muslo medio de Lee. Es una de las cinco masas de Kerr: las cinco suman el peso estructurado, que se compara con el peso medido.","fuente":"Kerr DA. An anthropometric method for fractionation of skin, adipose, bone, muscle and residual tissue masses, in males and females age 6 to 77 years [tesis de maestría]. Burnaby: Simon Fraser University; 1988. Ecuaciones de la tabla 4.3 y sitios del apéndice A. https://summit.sfu.ca/item/5139. Ross WD, Kerr DA. Apunts Med Esport. 1991;28:175-188.","poblacion":"Un humano de referencia unisex (el Phantom de Ross y Wilson) probado en 1669 personas de 6 a 77 años, de 11 muestras: la suma de las cinco masas dio en promedio 1,1 kg (1,6 %) más que el peso medido, y quedó dentro del 4 % salvo en fisicoculturistas (8 %). La coherencia de cada masa se controló con la disección de 25 cadáveres.","categoria":"MASAS"}',
